public List<Edge> routeTo(Vertex vertex) {
    if (!hasRouteTo(vertex)) {
        return null;
    }

    List<Edge> routeList = new ArrayList<>();
    Edge edgeVar = edgeTo(vertex);
    while (edgeVar != null) {
        routeList.add(edgeVar);
        edgeVar = edgeTo(edgeVar.from());
    }
    Collections.reverse(routeList);
    return routeList;
}
